public static int calculateTimeNeeded(int N) {
    if (N < 2) {
        return 0;
    }
    if ((N & 1) == 0) { // even
        int k = N / 2;
        return k * (k - 1);
    } else { // odd
        int k = (N - 1) / 2;
        return k * k;
    }
}

