public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    int n = nums.length;
    boolean[] used = new boolean[n];

    class Backtracker {
        void dfs(List<Integer> current) {
            if (current.size() == n) {
                result.add(new ArrayList<>(current));
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                used[i] = true;
                current.add(nums[i]);
                dfs(current);
                current.remove(current.size() - 1);
                used[i] = false;
            }
        }
    }

    new Backtracker().dfs(new ArrayList<>());
    return result;
}

