        for (String s : candidates) {
            String rev = new StringBuilder(s).reverse().toString();
            boolean ok = true;
            for (int idx = 1; idx < strings.size(); idx++) {
                String curr = strings.get(idx);
                if (!(curr.contains(s) || curr.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
