public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Special case: start equals end
    if (java.util.Arrays.equals(start, end)) {
        return "can be travelled";
    }

    // Determine if the problem uses node indices (i.e., start, end and paths contain single integers)
    boolean indexMode = start.length == 1 && end.length == 1;
    if (indexMode) {
        // Verify all paths are two-element arrays
        for (int[] p : paths) {
            if (p.length != 2) {
                indexMode = false;
                break;
            }
        }
    }

    if (indexMode) {
        // Build adjacency list using indices
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new java.util.ArrayList<>();
        }
        for (int[] p : paths) {
            int u = p[0];
            int v = p[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            adj[u].add(v);
            adj[v].add(u);
        }
        int startIdx = start[0];
        int endIdx = end[0];
        if (startIdx < 0 || startIdx >= n || endIdx < 0 || endIdx >= n) {
            return "cannot be travelled";
        }
        boolean[] visited = new boolean[n];
        java.util.Queue<Integer> queue = new java.util.LinkedList<>();
        queue.offer(startIdx);
        visited[startIdx] = true;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (cur == endIdx) {
                return "can be travelled";
            }
            for (int neigh : adj[cur]) {
                if (!visited[neigh]) {
                    visited[neigh] = true;
                    queue.offer(neigh);
                }
            }
        }
        return "cannot be travelled";
    } else {
        // Assume coordinates representation
        int coordSize = start.length;
        if (coordSize == 0) {
            return "cannot be travelled";
        }
        java.util.Map<String, Integer> nodeId = new java.util.HashMap<>();
        java.util.List<Integer>[] adj = new java.util.ArrayList[paths.length + 2]; // approximate size
        int idCounter = 0;
