            int[] nodeA = java.util.Arrays.copyOfRange(p, 0, coordSize);
            int[] nodeB = java.util.Arrays.copyOfRange(p, coordSize, 2 * coordSize);
            addNode.accept(nodeA);
            addNode.accept(nodeB);
            int aId = nodeId.get(java.util.Arrays.toString(nodeA));
            int bId = nodeId.get(java.util.Arrays.toString(nodeB));
            adj[aId].add(bId);
            adj[bId].add(aId);
        }
        int sId = nodeId.get(java.util.Arrays.toString(start));
        int eId = nodeId.get(java.util.Arrays.toString(end));
