    java.time.LocalDate localDate = java.time.LocalDate.parse(date, inputFormatter);
    java.time.format.DateTimeFormatter outputFormatter = java.time.format.DateTimeFormatter.ofPattern("MMMM d, yyyy");
    String formattedDate = localDate.format(outputFormatter);
    String dayOfWeek = localDate.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    return formattedDate + " is a " + dayOfWeek;
}

