public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) return false;
    int[] modCount = new int[k];
    for (int num : arr) {
        int r = Math.floorMod(num, k);
        modCount[r]++;
    }

    // Remainder 0 must have even count
    if (modCount[0] % 2 != 0) return false;

    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0 && modCount[k / 2] % 2 != 0) return false;

    // For other remainders, counts must pair up
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) { // already handled k even case
            continue;
        }
        if (modCount[i] != modCount[k - i]) {
            return false;
        }
    }
    return true;
}

