public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int sumAll = 0;
    for (int v : nums) sumAll += v;
    int n1 = n / 2;
    int n2 = n - n1;
    java.util.HashMap<Integer, java.util.HashSet<Integer>> leftSums = new java.util.HashMap<>();
    java.util.HashMap<Integer, java.util.HashSet<Integer>> rightSums = new java.util.HashMap<>();
    // Subsets for left half
    for (int mask = 0; mask < (1 << n1); mask++) {
        int size = Integer.bitCount(mask);
        int s = 0;
        for (int i = 0; i < n1; i++) {
            if ((mask & (1 << i)) != 0) s += nums[i];
        }
        leftSums.computeIfAbsent(size, k -> new java.util.HashSet<>()).add(s);
    }
    // Subsets for right half
    for (int mask = 0; mask < (1 << n2); mask++) {
        int size = Integer.bitCount(mask);
        int s = 0;
        for (int i = 0; i < n2; i++) {
            if ((mask & (1 << i)) != 0) s += nums[n1 + i];
        }
        rightSums.computeIfAbsent(size, k -> new java.util.HashSet<>()).add(s);
    }
    // Try all possible group sizes k (from 1 to n/2)
    for (int k = 1; k <= n / 2; k++) {
        long targetLong = (long) sumAll * k;
        if (targetLong % n != 0) continue;
        int target = (int) (targetLong / n);
        for (int s1 = 0; s1 <= k; s1++) {
            int s2 = k - s1;
            java.util.Set<Integer> set1 = leftSums.getOrDefault(s1, java.util.Collections.emptySet());
            java.util.Set<Integer> set2 = rightSums.getOrDefault(s2, java.util.Collections.emptySet());
            if (set1.isEmpty() || set2.isEmpty()) continue;
            for (int sum1 : set1) {
                if (set2.contains(target - sum1)) {
                    return true;
                }
            }
        }
    }
    return false;
}

