public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;
    int mask = total - 1;
    boolean[] seen = new boolean[total];
    int curr = 0;
    for (int i = 0; i < k; i++) {
        curr = (curr << 1) | (s.charAt(i) - '0');
    }
    seen[curr] = true;
