public int kthFactor(int n, int k) {
    int count = 0;
    int limit = (int) Math.sqrt(n);
    // Count lower factors (including sqrt if perfect square)
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }
    // Count upper factors by iterating the corresponding pairs in reverse order
    for (int i = limit; i >= 1; i--) {
        if (n % i == 0) {
            int partner = n / i;
            if (i == partner) {
                // Skip the square root duplicate
                continue;
            }
            count++;
            if (count == k) {
                return partner;
            }
        }
    }
    return -1;
}

