public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    int absValue = Math.abs(n);
    String s = Integer.toString(absValue);
    int len = s.length();
    StringBuilder result = new StringBuilder();
    int firstGroupLen = len % 3;
    if (firstGroupLen == 0) {
        firstGroupLen = 3;
    }
    result.append(s, 0, firstGroupLen);
    for (int i = firstGroupLen; i < len; i += 3) {
        result.append('.');
        result.append(s, i, i + 3);
