    int n = A.length;
    int[] arr = A.clone();
    Arrays.sort(arr);
    // Precompute perfect squares up to 2*max
    int maxVal = arr[n - 1];
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 1; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // Build adjacency list
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[arr[i] + arr[j]]) {
                adj[i].add(j);
            }
        }
    }
    boolean[] used = new boolean[n];
    int[] count = new int[1];

    // DFS
    void dfs(int pos, int lastIdx) {
        if (pos == n) {
            count[0]++;
            return;
        }
        for (int i = 0; i < n; i++) {
            if (used[i]) continue;
            // skip duplicates
            if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) continue;
            if (lastIdx == -1) {
                used[i] = true;
                dfs(pos + 1, i);
                used[i] = false;
            } else {
                // check adjacency
                if (isSquare[arr[lastIdx] + arr[i]]) {
                    used[i] = true;
                    dfs(pos + 1, i);
                    used[i] = false;
                }
            }
        }
    }

    dfs(0, -1);
    return count[0];
}

