        totalCounts[i] = countMap.get(vals.get(i));
    }
    // Precompute which pairs sum to a perfect square
    int maxVal = vals.stream().max(Integer::compareTo).orElse(0);
    int maxSum = 2 * maxVal;
    java.util.Set<Integer> squares = new java.util.HashSet<>();
    for (int k = 1; k * k <= maxSum; k++) {
        squares.add(k * k);
    }
    boolean[][] can = new boolean[m][m];
    for (int i = 0; i < m; i++) {
