public static int squarePermutations(int[] A) {
    int n = A.length;
    // Sort array to handle duplicates
    java.util.Arrays.sort(A);

    // Determine perfect squares up to 2*max(A)
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) maxVal = v;
    }
    int maxSum = 2 * maxVal;
    java.util.HashSet<Integer> squares = new java.util.HashSet<>();
    for (int i = 2; i * i <= maxSum; i++) {
        squares.add(i * i);
    }

    // Build adjacency list of indices where sums are perfect squares
    java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
    for (int i = 0; i < n; i++) {
        java.util.List<Integer> list = new java.util.ArrayList<>();
        for (int j = 0; j < n; j++) {
            if (i != j && squares.contains(A[i] + A[j])) {
                list.add(j);
            }
        }
        adj.add(list);
    }

    boolean[] used = new boolean[n];

    java.util.function.IntBinaryOperator skipDupCheck = (idx, lastUsed) -> {
        if (idx > 0 && A[idx] == A[idx - 1] && !used[idx - 1]) {
            return 1; // indicate skip
        }
        return 0;
    };

    java.util.concurrent.atomic.AtomicInteger total = new java.util.concurrent.atomic.AtomicInteger(0);

    java.util.function.BiFunction<Integer, Integer, Integer> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Integer apply(Integer last, Integer count) {
            if (count == n) return 1;
            int sum = 0;
            for (int nxt : adj.get(last)) {
                if (!used[nxt]) {
                    if (skipDupCheck.applyAsInt(nxt, last) != 0) continue;
                    used[nxt] = true;
                    sum += this.apply(nxt, count + 1);
                    used[nxt] = false;
                }
            }
            return sum;
        }
    };

    for (int i = 0; i < n; i++) {
        if (skipDupCheck.applyAsInt(i, -1) != 0) continue;
        used[i] = true;
        total.addAndGet(dfs.apply(i, 1));
        used[i] = false;
    }

    return total.get();
}

