        java.util.List<Integer> list = new java.util.ArrayList<>();
        for (int j = 0; j < n; j++) {
            if (i != j && squares.contains(A[i] + A[j])) {
                list.add(j);
            }
        }
        adj.add(list);
    }

    boolean[] used = new boolean[n];

    java.util.function.IntBinaryOperator skipDupCheck = (idx, lastUsed) -> {
        if (idx > 0 && A[idx] == A[idx - 1] && !used[idx - 1]) {
            return 1; // indicate skip
        }
        return 0;
    };

    java.util.concurrent.atomic.AtomicInteger total = new java.util.concurrent.atomic.AtomicInteger(0);

    java.util.function.BiFunction<Integer, Integer, Integer> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Integer apply(Integer last, Integer count) {
