            int sum = 0;
            for (int nxt : adj.get(last)) {
                if (!used[nxt]) {
                    if (skipDupCheck.applyAsInt(nxt, last) != 0) continue;
                    used[nxt] = true;
                    sum += this.apply(nxt, count + 1);
                    used[nxt] = false;
                }
            }
            return sum;
        }
    };

    for (int i = 0; i < n; i++) {
        if (skipDupCheck.applyAsInt(i, -1) != 0) continue;
        used[i] = true;
        total.addAndGet(dfs.apply(i, 1));
        used[i] = false;
    }

    return total.get();
