    digits[i] = digits[j];
    digits[j] = temp;

    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    int result = 0;
    for (int d : digits) {
        result = result * 10 + d;
    }

    return result > n ? result : -1;
}

