public static int findSmallestInteger(int n) {
    String numStr = Integer.toString(n);
    char[] digits = numStr.toCharArray();
    // Find the pivot
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    // Find the smallest digit greater than pivot on the right
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // Swap pivot with j
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Reverse the suffix
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    int result = Integer.parseInt(new String(digits));
    return result > n ? result : -1;
}

